+<?php
+declare(strict_types=1);
+
+namespace Inpsyde\BackWPup\Tests\Integration\src\Admin\Notices\Notices;
+
+use Inpsyde\BackWPup\Tests\Integration\TestCase;
+use function Brain\Monkey\Functions\when;
+use WPMedia\BackWPup\Admin\Notices\Notices\NoticeUpgradeToPro;
+use Inpsyde\BackWPup\Notice\NoticeView;
+
+/**
+ * Integration tests for NoticeUpgradeToPro
+ * 
+ * @group Admin
+ */
+class NoticeUpgradeToProTest extends TestCase {
+
+    /**
+     * @dataProvider configTestData
+     */
+	public function testShouldReturnAsExpected( $config, $expected ) {
+        $was_pro = \BackWPup::is_pro();
+        if ( isset( $config['is_pro'] ) ) {
+            \BackWPup::set_is_pro( $config['is_pro'] );
+        }
+        if (isset($config['user_id'])) {
+            when('get_current_user_id')->justReturn($config['user_id']);
+        }
+        if (isset($config['current_screen'])) {
+            when('get_current_screen')->justReturn((object) ['id' => $config['current_screen']]);
+        }
+        if (isset($config['user_metas']) && isset($config['user_id'])) {
+            foreach ($config['user_metas'] as $meta_key => $meta_value) {
+                update_user_meta($config['user_id'], $meta_key, $meta_value);
+            }
+        }
+        $notice_view = new NoticeView(NoticeUpgradeToPro::ID);
+        $notice = new NoticeUpgradeToPro( $notice_view );
+        ob_start();
+        $notice->maybe_render();
+        $render = ob_get_clean();
+
+        if (isset($expected['should_render']) && $expected['should_render']) {
+            $this->assertNotEmpty($render);
+        } else if (isset($expected['should_render']) && ! $expected['should_render']) {
+            $this->assertEmpty($render);
+        }
+
+        if ( isset( $config['is_pro'] ) ) {
+            \BackWPup::set_is_pro( $was_pro );
+        }
+        if (isset($config['user_metas']) && isset($config['user_id'])) {
+            foreach ($config['user_metas'] as $meta_key => $meta_value) {
+                delete_user_meta($config['user_id'], $meta_key);
+            }
+        }
+    }
+
+	
+}
