const { test, expect } = require('@playwright/test');

const BASE = 'http://localhost:8888';
const SS = '/Users/gaelrobin/Local Sites/bwu/app/public/wp-content/plugins/backwpup-pro/.e2e-screenshots';

async function login(page) {
  await page.goto(`${BASE}/wp-login.php`);
  await page.fill('#user_login', 'admin');
  await page.fill('#user_pass', 'password');
  await page.click('#wp-submit');
  await page.waitForURL('**/wp-admin/**');
}

test('AC-storage-sidebar — PRO badge and upgrade card visible for free users', async ({ page }) => {
  await login(page);

  // Go to jobs list (dashboard) where the Storage tab link lives
  await page.goto(`${BASE}/wp-admin/admin.php?page=backwpup`);
  await page.waitForLoadState('networkidle');

  // Click the Storage button to open the storage sidebar
  const storageBtn = page.locator('button.js-backwpup-load-and-open-sidebar[data-content="storages"]').first();
  await storageBtn.click();
  await page.waitForTimeout(1200);

  // Verify the PRO badge is visible on a locked storage item
  const proBadge = page.locator('.js-backwpup-locked-storage .bg-pro, [class*="bg-pro"]').first();
  const upgradeCard = page.locator('text=Unlock more storage options').first();

  await page.screenshot({ path: `${SS}/pr1657-06-storage-sidebar.png`, fullPage: true });

  // Assert key elements are present
  await expect(upgradeCard).toBeVisible({ timeout: 5000 });
  await expect(proBadge).toBeVisible({ timeout: 5000 });

  // Scroll to top first to show storages list
  const scrollable = page.locator('.relative.flex-auto.overflow-y-auto').first();
  await scrollable.evaluate(el => el.scrollTop = 0);
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${SS}/pr1657-06-storage-sidebar-top.png`, fullPage: true });

  // Scroll to bottom to reveal upgrade card and PRO badges
  await scrollable.evaluate(el => el.scrollTop = el.scrollHeight);
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${SS}/pr1657-07-storage-sidebar-bottom.png`, fullPage: true });
});
